"""Exact independent enumeration of square-zero endomorphism images for C_p + C_{p^b}."""
from itertools import product

def computed(p,b):
    n=p**b
    # independent image subgroup generated by image of (1,0) and (0,1)
    # X(a,c)=(u*a+v*c mod p, p^(b-1)*w*a+z*c mod p^b)
    # the endomorphism is square zero precisely when images of both generators map to zero
    counts={}
    for u,v,w in product(range(p),repeat=3):
        for z in range(n):
            # image of first standard generator is (u,p^(b-1)*w)
            aa=(u*u+v*(p**(b-1)*w))%p
            ab=(p**(b-1)*w*u+z*p**(b-1)*w)%n
            # image of second standard generator is (v,z)
            ba=(u*v+v*z)%p
            bb=(p**(b-1)*w*v+z*z)%n
            if any([aa,ab,ba,bb]):continue
            generators=[(u,p**(b-1)*w),(v,z)]
            image={(0,0)}
            for a in range(p):
                for c in range(n):
                    image.add(((a*u+c*v)%p,(a*p**(b-1)*w+c*z)%n))
            size=len(image)
            def order(g):
                # Exact order of an element in the direct sum of cyclic p-groups.
                a,c=g
                for j in range(b+1):
                    if (p**j*a)%p==0 and (p**j*c)%n==0:
                        return p**j
                raise AssertionError('unreachable')
            assert size==max(order(t) for t in generators), (p,b,u,v,w,z,size)
            assert size in (p**j for j in range(b+1))
            j=next(j for j in range(b+1) if p**j==size)
            counts[j]=counts.get(j,0)+1
    return counts

def predicted(p,b):
    if b==1:
        return {0:1,1:p*p-1}
    s=b//2
    d={0:1,1:(2*p+1)*(p-1)}
    for j in range(2,s+1):d[j]=(2*p-1)*(p-1)*p**(j-1)
    if b%2:d[s+1]=(p-1)**2*p**s
    return d

if __name__=='__main__':
    for p,b in [(2,1),(3,1),(2,2),(3,2),(5,2),(2,3),(3,3),(5,3),(2,4),(3,4),(2,5),(3,5),(2,6),(2,7)]:
        got=computed(p,b);want=predicted(p,b)
        assert got==want,(p,b,got,want)
        print('OK',p,b,got,'total',sum(got.values()))
    print('VERIFY_OK')
